// Genuine rmcp 3.6 client lifecycle and typed tools/call requests over the
// selected OAuth Gateway. Metadata is generated by ClientServiceExt's Discover
// lifecycle; only the operation arguments and bearer are supplied here.
use super::*;
use super::current_state as state;
use rmcp::{
    model::{CallToolRequestParams, ClientCapabilities, ClientConfig, Implementation, ProtocolVersion},
    transport::{
        streamable_http_client::{
            SseError, StreamableHttpClient, StreamableHttpClientTransport,
            StreamableHttpClientTransportConfig, StreamableHttpError,
            StreamableHttpPostResponse,
        },
    },
    ClientLifecycleMode, ClientServiceExt,
};
use futures::stream::BoxStream;
use serde_json::{json, Value};
use std::{borrow::Cow, collections::HashMap, sync::{Arc, Mutex}};
use sse_stream::Sse;
use tower::ServiceExt;

#[derive(Clone)]
struct InProcessMcpHttpClient {
    app: axum::Router,
    wire_requests: Arc<Mutex<Vec<Value>>>,
}

impl StreamableHttpClient for InProcessMcpHttpClient {
    type Error = std::io::Error;

    async fn post_message(
        &self,
        _uri: Arc<str>,
        message: rmcp::model::ClientJsonRpcMessage,
        _session_id: Option<Arc<str>>,
        auth_header: Option<String>,
        custom_headers: HashMap<axum::http::HeaderName, axum::http::HeaderValue>,
    ) -> Result<StreamableHttpPostResponse, StreamableHttpError<Self::Error>> {
        let json = serde_json::to_value(&message)?;
        self.wire_requests.lock().unwrap().push(json.clone());
        let body = serde_json::to_vec(&json)?;
        let mut builder = axum::http::Request::builder()
            .method("POST")
            .uri("/mcp")
            .header("Content-Type", "application/json")
            .header("Accept", "application/json, text/event-stream");
        if let Some(token) = auth_header {
            builder = builder.header("Authorization", format!("Bearer {token}"));
        }
        for (name, value) in custom_headers {
            builder = builder.header(name, value);
        }
        let request = builder
            .body(axum::body::Body::from(body))
            .map_err(std::io::Error::other)?;
        let response = self
            .app
            .clone()
            .oneshot(request)
            .await
            .expect("in-process Axum MCP service is infallible");
        let status = response.status();
        let bytes = axum::body::to_bytes(response.into_body(), 65_536)
            .await
            .map_err(|error| std::io::Error::other(error.to_string()))?;
        if status != axum::http::StatusCode::OK {
            return Err(StreamableHttpError::UnexpectedServerResponse(
                format!("in-process MCP server returned {status}: {}", String::from_utf8_lossy(&bytes)).into(),
            ));
        }
        let response = serde_json::from_slice(&bytes)?;
        Ok(StreamableHttpPostResponse::Json(response, None))
    }

    async fn delete_session(
        &self,
        _uri: Arc<str>,
        _session_id: Arc<str>,
        _auth_header: Option<String>,
        _custom_headers: HashMap<axum::http::HeaderName, axum::http::HeaderValue>,
    ) -> Result<(), StreamableHttpError<Self::Error>> {
        Ok(())
    }

    async fn get_stream(
        &self,
        _uri: Arc<str>,
        _session_id: Option<Arc<str>>,
        _last_event_id: Option<String>,
        _auth_header: Option<String>,
        _custom_headers: HashMap<axum::http::HeaderName, axum::http::HeaderValue>,
    ) -> Result<BoxStream<'static, Result<Sse, SseError>>, StreamableHttpError<Self::Error>> {
        Err(StreamableHttpError::UnexpectedServerResponse(Cow::Borrowed(
            "this JSON-only test client does not open SSE streams",
        )))
    }
}

pub(super) async fn client_call_on_gateway(
    app: axum::Router,
    bearer: String,
    client_name: &str,
    operation: &str,
    request_key: &str,
    input: Value,
) -> Value {
    let mut headers = HashMap::new();
    headers.insert(
        axum::http::header::HOST,
        axum::http::HeaderValue::from_static("127.0.0.1:28788"),
    );
    let wire_requests = Arc::new(Mutex::new(Vec::new()));
    let transport = StreamableHttpClientTransport::with_client(
        InProcessMcpHttpClient {
            app,
            wire_requests: wire_requests.clone(),
        },
        StreamableHttpClientTransportConfig::with_uri("http://127.0.0.1:28788/mcp")
            .auth_header(bearer)
            .custom_headers(headers),
    );
    let client = ClientConfig::new(
        ClientCapabilities::default(),
        Implementation::new(client_name, "1"),
    )
    .serve_with_lifecycle(
        transport,
        ClientLifecycleMode::Discover {
            preferred_versions: vec![ProtocolVersion::V_2026_07_28],
        },
    )
    .await
    .expect("real rmcp client discovers stateless protocol");

    let arguments = json!({
        "address":"@own-records",
        "method":operation,
        "request_key":request_key,
        "input":input,
    })
    .as_object()
    .unwrap()
    .clone();
    let result = client
        .call_tool(
            CallToolRequestParams::new("run_resource_operation")
                .with_arguments(arguments),
        )
        .await
        .expect("typed rmcp tools/call reaches selected Gateway");
    client.cancel().await.expect("cancel rmcp client");
    let call = wire_requests
        .lock()
        .unwrap()
        .iter()
        .find(|message| message["method"] == "tools/call")
        .cloned()
        .expect("the rmcp client emitted tools/call over its HTTP transport");
    assert_eq!(
        call.pointer("/params/_meta/io.modelcontextprotocol~1protocolVersion")
            .and_then(Value::as_str),
        Some("2026-07-28"),
        "Discover lifecycle must put the protocol version on every stateless request",
    );
    assert!(call.pointer("/params/_meta/io.modelcontextprotocol~1clientCapabilities").is_some());
    assert_eq!(
        call.pointer("/params/_meta/io.modelcontextprotocol~1clientInfo/name")
            .and_then(Value::as_str),
        Some(client_name),
        "each actual client supplies its own metadata through the SDK lifecycle",
    );

    assert_ne!(result.is_error, Some(true),
        "synthetic SDK request {request_key} must succeed; code={:?}",
        result.structured_content.as_ref().and_then(|value| value["code"].as_str()));
    result.structured_content.expect("structured operation result")
}

async fn client_tool_call(
    fixture: &Fixture,
    issuer: Arc<super::oauth_test_support::SyntheticOAuthIssuer>,
    client_name: &str,
    operation: &str,
    request_key: &str,
    input: Value,
) -> Value {
    let (app, gateway, mac) = super::oauth_read_consumer_controls::start_selected_gateway(
        fixture, issuer.clone(),
    )
    .await;
    let result = client_call_on_gateway(
        app,
        issuer.bearer(),
        client_name,
        operation,
        request_key,
        input,
    )
    .await;
    drop(gateway);
    mac.join().unwrap().unwrap();
    result
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn rmcp_36_oauth_client_calls_selected_read_without_handcrafted_metadata() {
    let fixture = Fixture::new_with_oauth_grant();
    let issuer = Arc::new(super::oauth_test_support::SyntheticOAuthIssuer::new(&fixture));
    let before = state(&fixture);
    let result = client_tool_call(
        &fixture,
        issuer.clone(),
        "synthetic-oauth-reader",
        "workspace:read",
        "oauth-rmcp-read-current",
        json!({}),
    )
    .await;

    assert_eq!(result["status"], 200);
    assert_eq!(result["request_key"], "oauth-rmcp-read-current");
    assert!(result["text"].as_str().unwrap().contains("saved-board"));
    assert!(issuer.requests() >= 3, "issuer checks Gateway, selected dispatch, and result release");
    assert_eq!(state(&fixture), before, "read has no business-record writes");
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn rmcp_36_oauth_client_commits_selected_write_and_releases_protected_result() {
    let fixture = Fixture::new_with_oauth_grant();
    let issuer = Arc::new(super::oauth_test_support::SyntheticOAuthIssuer::new(&fixture));
    let before = state(&fixture);
    let result = client_tool_call(
        &fixture,
        issuer.clone(),
        "synthetic-oauth-writer",
        "workspace:write",
        "oauth-rmcp-write-current",
        input(),
    )
    .await;

    assert_eq!(result["written"], 1, "canonical workspace write result reports one committed write");
    let after = state(&fixture);
    assert!(after.0.contains("written"));
    assert!(after.1 > before.1, "original record log contains the committed write");
    assert_eq!(after.2, before.2 + 1, "one SDK call creates one original command");
    assert!(issuer.requests() >= 4, "issuer checks admission, selected dispatch, and protected release");
}


#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn rmcp_36_oauth_independent_clients_share_selected_committed_read_state() {
    let fixture = Fixture::new_with_oauth_grant();
    let issuer = Arc::new(super::oauth_test_support::SyntheticOAuthIssuer::new(&fixture));
    let initial = state(&fixture);
    let (app, gateway, mac) = super::oauth_read_consumer_controls::start_selected_gateway(
        &fixture, issuer.clone(),
    )
    .await;

    // This overlay supports one synthetic OAuth grant. Two independent rmcp
    // client lifecycles deliberately share that same grant and Gateway; it
    // proves same-token, same-owner read-your-writes over sessionless MCP.
    let write = client_call_on_gateway(
        app.clone(),
        issuer.bearer(),
        "synthetic-oauth-writer-client",
        "workspace:write",
        "oauth-rmcp-shared-idea-write",
        json!({"writes":[{"address_label":"saved-board","payload":{"items":["shared-idea-from-client-a"]}}],"conflict_policy":"retry"}),
    )
    .await;
    assert_eq!(write["written"], 1, "canonical workspace write result reports one committed write");
    let after_write = state(&fixture);
    assert!(after_write.0.contains("shared-idea-from-client-a"));
    assert!(after_write.1 > initial.1);
    assert_eq!(after_write.2, initial.2 + 1);

    let read = client_call_on_gateway(
        app,
        issuer.bearer(),
        "synthetic-oauth-reader-client",
        "workspace:read",
        "oauth-rmcp-shared-idea-read",
        json!({}),
    )
    .await;
    assert_eq!(read["status"], 200);
    assert_eq!(read["request_key"], "oauth-rmcp-shared-idea-read");
    assert!(read["text"].as_str().unwrap().contains("shared-idea-from-client-a"),
        "client B must read the committed value from client A through the same selected Mac");
    let after_read = state(&fixture);
    assert_eq!(after_read, after_write, "client B's read observes A's commit without a second write");
    assert!(issuer.requests() >= 7, "both independent client calls pass issuer validation and protected-result checks");

    drop(gateway);
    mac.join().unwrap().unwrap();
}
